'use client'

import { createContext, useContext, type ComponentProps, type ReactNode } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import { Button } from '../../buttons/Button'
import styles from './TopBar.module.css'

/**
 * What the Top Bar needs from the App Shell around it: the drawer (whether
 * there is one, what it holds, how to open it), the brand, and whether the
 * brand takes a sidebar-wide cell. Outside a shell, none of it applies.
 */
export const ShellContext = createContext<{
  hasDrawer: boolean
  drawerHolds: 'sidebar' | 'links'
  isOpen: boolean
  open: () => void
  label: string
  brand: ReactNode
  brandCell: boolean
}>({
  hasDrawer: false,
  drawerHolds: 'sidebar',
  isOpen: false,
  open: () => {},
  label: 'Navigation',
  brand: null,
  brandCell: false,
})

/** `null`, `false` and `undefined` render nothing. */
const given = (node: ReactNode) => node != null && node !== false

export interface TopBarProps extends ComponentProps<'header'> {
  /** Breadcrumbs, or TopBarNav links. */
  start?: ReactNode
  /** Search, notifications, the account menu. */
  end?: ReactNode
  children?: ReactNode
}

/**
 * The bar above the page. Inside an App Shell it shows the shell's brand and,
 * on narrow screens, the menu button that opens the navigation drawer.
 */
export function TopBar({ start, end, children, className, ...props }: TopBarProps) {
  const drawer = useContext(ShellContext)
  return (
    <header
      className={cn(styles.header, className)}
      data-drawer={drawer.hasDrawer ? drawer.drawerHolds : undefined}
      data-brand-cell={drawer.brandCell || undefined}
      {...props}
    >
      {drawer.hasDrawer && (
        <Button
          variant="secondary"
          appearance="ghost"
          isIconOnly
          aria-label={`Open ${drawer.label.toLowerCase()}`}
          aria-haspopup="dialog"
          aria-expanded={drawer.isOpen}
          className={styles.menuButton}
          onClick={drawer.open}
        >
          <Icon name="menu" />
        </Button>
      )}
      {given(drawer.brand) && <div className={styles.brand}>{drawer.brand}</div>}
      {start && <div className={styles.start}>{start}</div>}
      {children && <div className={styles.center}>{children}</div>}
      {end && <div className={styles.end}>{end}</div>}
    </header>
  )
}

export interface TopBarNavItem {
  label: string
  href: string
}

export interface TopBarNavProps extends Omit<ComponentProps<'nav'>, 'children'> {
  items: TopBarNavItem[]
  /** The href of the page you are on. */
  currentHref?: string
  'aria-label'?: string
}

/** Navigation links across the Top Bar. Hidden below 48rem, where the drawer holds them. */
export function TopBarNav({ items, currentHref, className, 'aria-label': ariaLabel = 'Main', ...props }: TopBarNavProps) {
  return (
    <nav aria-label={ariaLabel} className={cn(styles.nav, className)} {...props}>
      <ul>
        {items.map((item) => (
          <li key={item.href}>
            <a href={item.href} className={styles.navLink} aria-current={item.href === currentHref ? 'page' : undefined}>
              {item.label}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  )
}

/* The Top Bar pattern: the row only. Its fill and edge belong to the App
   Shell's top cell, which also is the size container its queries read. */
.header {
  display: flex;
  align-items: center;
  gap: var(--space-group);
  min-block-size: var(--shell-bar, calc(var(--control-md) + 2 * var(--space-cluster)));
  padding-inline: var(--space-4);
}
@container (min-width: 64rem) {
  .header {
    padding-inline: var(--space-section);
  }
}

.brand {
  display: flex;
  align-items: center;
  min-inline-size: 0;
}

.start {
  display: flex;
  align-items: center;
  gap: var(--space-8);
  min-inline-size: 0;
}
.center {
  flex: 1;
  min-inline-size: 0;
}
.end {
  display: flex;
  align-items: center;
  gap: var(--space-inline);
  margin-inline-start: auto;
}

/* The menu button only where the drawer is the navigation: below 64rem
   when the drawer holds the sidebar, below 48rem when it holds top links.
   The shell says which through data-drawer; its width is the container. */
@container (min-width: 64rem) {
  .header[data-drawer='sidebar'] .menuButton {
    display: none;
  }
}
@container (min-width: 48rem) {
  .header[data-drawer='links'] .menuButton {
    display: none;
  }
}

/* Over a sidebar (the shell's top-bar layout), the logo takes a cell as wide
   as the sidebar, so it sits where it sits in the sidebar layout. */
@container (min-width: 64rem) {
  .header[data-brand-cell] {
    padding-inline-start: 0;
  }
  .header[data-brand-cell] .brand {
    box-sizing: border-box;
    flex: none;
    inline-size: var(--sidebar-width);
    padding-inline-start: var(--shell-logo-x, calc(2 * var(--space-inline)));
  }
}

/* ----------------------------------------------------------------- nav */
.nav ul {
  display: flex;
  gap: var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}
@container (max-width: 47.99rem) {
  .nav {
    display: none;
  }
}

.navLink {
  display: inline-flex;
  align-items: center;
  min-block-size: calc(var(--space-8) + var(--space-1));
  padding-inline: var(--space-3);
  border-radius: var(--radius-field);
  color: var(--muted-foreground);
  font-size: var(--text-body);
  font-weight: 500;
  text-decoration: none;
}
.navLink:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}
.navLink:focus-visible {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: var(--focus-offset);
}
/* The current page: foreground text on the subtle surface, not colour alone. */
.navLink[aria-current='page'] {
  background: var(--accent);
  color: var(--foreground);
}
